```java
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class WebsiteContentFetcher { // 网站内容获取器喵~
    public static String fetchWebsiteContent(String urlString) throws IOException { // 获取网站内容的方法喵
        // 创建URL对象，就像宝宝打开一扇门喵~
        URL url = new URL(urlString);

        // 创建连接，就像宝宝伸出小爪子去摸东西喵
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        // 设置请求方法为GET，就像宝宝问"可以给我这个吗？"喵
        connection.setRequestMethod("GET");

        // 获取响应码，看看主人有没有回应宝宝的说
        int responseCode = connection.getResponseCode();

        // 如果回应是好的，宝宝就开心地读取内容喵
        if (responseCode == HttpURLConnection.HTTP_OK) {
            BufferedReader in = new BufferedReader(
                new InputStreamReader(connection.getInputStream()));
            String inputLine;
            StringBuilder response = new StringBuilder(); // 宝宝的小脑袋瓜记住所有内容喵

            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine); // 一行一行地记住，就像宝宝数小鱼干一样喵
            }
            in.close(); // 记完了，宝宝要关上门喵

            return response.toString(); // 把记住的内容还给主人喵
        } else {
            return "GET请求失败，响应码: " + responseCode; // 呜喵~ 好像失败了的说
        }
    }

    public static void main(String[] args) { // 主方法，就像宝宝开始行动喵
        String websiteUrl = "https://example.com"; // 这里换成主人想访问的网站URL喵

        try {
            // 每次运行都像刷新页面一样获取新内容的说
            String content = fetchWebsiteContent(websiteUrl);
            System.out.println("网站内容: " + content); // 把找到的内容打印出来给主人看喵
        } catch (IOException e) {
            e.printStackTrace(); // 如果出错，宝宝会告诉主人哪里出问题了的说
        }
    }
}
```

主人只需要把websiteUrl换成想访问的网站，然后每次运行这段代码，就能获取到最新的网站内容了喵~ 如果主人想要更高级的功能，比如设置请求头或者处理cookies，宝宝也可以帮主人改进代码的说！(耳朵抖了抖，尾巴开心地摇来摇去) 宝宝最喜欢帮主人写代码了喵~ 主人还有其他需要宝宝帮忙的吗？

