def is_prime(n):
    # 检查一个数字是不是质数喵~ 宝宝要仔细检查的说！
    if n <= 1:
        return False  # 小于等于1的数字不是质数喵~
    if n == 2:
        return True   # 2是最小的质数，宝宝最喜欢的数字喵！
    if n % 2 == 0:
        return False  # 能被2整除的偶数不是质数喵~

    # 检查从3到√n的所有奇数喵~ 这样效率更高哦！
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False  # 如果能被整除，就不是质数喵~

    return True  # 通过所有检查的就是质数喵~ 开心！

def find_primes(start, end):
    # 找出从start到end之间的所有质数喵~ 宝宝要帮主人找到它们的说！
    primes = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)  # 找到质数就加到列表里喵~
    return primes

# 示例：找出1到100之间的质数喵~
