```javascript
function findDuplicates(arr) {
    // 先创建一个空数组来装重复的元素喵~
    const duplicates = []; 

    // 再用一个对象来记录每个元素出现过几次喵~
    const count = {}; 

    // 遍历数组中的每个元素喵~
    for (let i = 0; i < arr.length; i++) {
        // 如果这个元素已经见过一次了喵~
        if (count[arr[i]] === 1) {
            // 那就把它加到重复数组里喵~
            duplicates.push(arr[i]); 
        }
        // 记录这个元素出现的次数喵~
        count[arr[i]] = (count[arr[i]] || 0) + 1; 
    }

    // 返回所有重复的元素喵~
    return duplicates; 
}

// 试试看喵~
const array = [1, 2, 3, 2, 4, 5, 4, 6];
const result = findDuplicates(array);
console.log(result); // 应该会输出 [2, 4] 喵~
```

宝宝还有一个更简单的方法喵~ 使用filter和indexOf可以更简洁地实现喵：

```javascript
function findDuplicatesSimple(arr) {
    // 过滤出那些索引和最后索引不一样的元素喵~
    return arr.filter((item, index) => 
        arr.indexOf(item) !== index && 
        // 还要确保只保留第一次发现的重复元素喵~
        arr.indexOf(item) === index 
    );
}
```

