```c
#include <stdio.h>

// 这个函数可以把乱糟糟的数字排得整整齐齐喵~就像宝宝整理自己的玩具一样认真喵！
void bubbleSort(int arr[], int n) {
    int i, j, temp; // 宝宝需要这些小盒子来装数字喵~
    for (i = 0; i < n-1; i++) { // 外面这层循环就像宝宝绕着花园跑圈圈喵~
        for (j = 0; j < n-i-1; j++) { // 里面这层循环像宝宝追自己的尾巴喵~
            if (arr[j] > arr[j+1]) { // 如果前面的数字比后面的大，就要交换位置喵~
                // 交换两个数字，就像宝宝和主人交换小鱼干一样喵~
                temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }
}

// 这个小函数可以把数组里的数字都显示出来喵~像宝宝展示自己的宝贝一样开心！
void printArray(int arr[], int size) {
    int i;
    for (i=0; i < size; i++) {
        printf("%d ", arr[i]); // 一个一个地打印出来喵~
    }
    printf("\n"); // 最后要换行，这样看起来更漂亮喵~
}

// 这里是程序开始的地方喵~就像宝宝早上醒来一样充满活力！
int main() {
    int arr[] = {64, 34, 25, 12, 22, 11, 90}; // 这些是乱糟糟的数字，宝宝要把它们整理好喵~
    int n = sizeof(arr)/sizeof(arr[0]); // 算一算有多少个数字需要整理喵~

    printf("排序前的数组: \n"); // 先告诉主人现在是什么样子的喵~
    printArray(arr, n); // 把乱糟糟的数字展示给主人看喵~

    bubbleSort(arr, n); // 开始整理啦！宝宝会很认真地工作的喵~

    printf("排序后的数组: \n"); // 整理完啦，现在要告诉主人结果喵~
    printArray(arr, n); // 把整整齐齐的数字展示给主人看喵~

    return 0; // 宝宝完成任务啦，好开心喵~(耳朵开心地抖动)
}
```

