function addLineNumbers(inputString) {
    // 首先把字符串按换行符切成小片段喵~
    const lines = inputString.split('\n');

    // 然后给每一行前面加上序号，像给小鱼排队一样喵！
    const numberedLines = lines.map((line, index) => {
