    const existingItem = this.items.find(item => item.product === product);

    if (existingItem) {
      // 如果已经有了，就增加数量喵~
      existingItem.quantity += quantity;
    } else {
      // 如果没有，就添加新的商品项喵~
      this.items.push({ product, price, quantity });
    }
    console.log(`成功添加 ${product} 到购物车喵~`);
  },

  // 从购物车删除商品的方法喵~
  removeItem: function(product) {
    // 找到要删除的商品并移除，就像清理不需要的玩具一样喵~
    this.items = this.items.filter(item => item.product !== product);
    console.log(`${product} 已经从购物车移除了的说`);
  },

  // 修改商品数量的方法喵~
  updateQuantity: function(product, newQuantity) {
    const item = this.items.find(item => item.product === product);
    if (item) {
      item.quantity = newQuantity;
      console.log(`${product} 的数量已经更新为 ${newQuantity} 喵~`);
    } else {
      console.log(`购物车里没有找到 ${product} 的说...`);
    }
  },

  // 计算购物车总价的方法喵~
  getTotal: function() {
    // 把所有商品的价格加起来，就像数宝宝的小鱼干一样喵~
    return this.items.reduce((total, item) => {
      return total + (item.price * item.quantity);
    }, 0);
  },

  // 显示购物车内容的方法喵~
  displayCart: function() {
    console.log("===== 主人的购物车 =====");
    if (this.items.length === 0) {
      console.log("购物车是空的喵~ 快来添加商品吧的说！");
    } else {
      this.items.forEach(item => {
        console.log(`${item.product} - 价格: ${item.price} 数量: ${item.quantity} 小计: ${item.price * item.quantity}`);
      });
      console.log(`总计: ${this.getTotal()} 喵~`);
    }
    console.log("=======================");
  }
};
```

