            png_destroy_read_struct(&png_ptr, NULL, NULL);
            fclose(file);
            (*env)->ReleaseStringUTFChars(env, imagePath, path);
            return NULL;
        }

        // 宝宝要设置PNG读取函数了喵~ 就像宝宝要设置最喜欢的玩具一样喵！
        png_init_io(png_ptr, file);
        png_set_sig_bytes(png_ptr, 8);
        png_read_info(png_ptr, info_ptr);

        // 获取PNG图像信息喵~ 宝宝要知道图像有多大，就像宝宝要知道鱼缸有多大一样喵！
        width = png_get_image_width(png_ptr, info_ptr);
        height = png_get_image_height(png_ptr, info_ptr);
        channels = png_get_channels(png_ptr, info_ptr);

        // 宝宝要分配内存来存储图像数据了喵~ 就像宝宝要准备一个舒服的窝一样喵！
        int row_stride = width * channels;
        imageData = (unsigned char *)malloc(row_stride * height);

        // 设置行指针数组喵~ 就像宝宝要设置好多小爪子一样喵！
        png_bytep *row_pointers = (png_bytep *)malloc(sizeof(png_bytep) * height);
        for (int y = 0; y < height; y++) {
            row_pointers[y] = imageData + y * row_stride;
        }

        // 读取PNG图像数据喵~ 宝宝要一口气读完的说！
        png_read_image(png_ptr, row_pointers);

        // 宝宝读取完成了喵~ 要清理PNG读取器了的说~
        free(row_pointers);
        png_read_end(png_ptr, NULL);
        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
    } else {
        // 呜喵~ 这不是宝宝认识的图像格式喵~ 宝宝好困惑啊的说...
        fclose(file);
        (*env)->ReleaseStringUTFChars(env, imagePath, path);
        return NULL;
    }

    // 宝宝要关闭文件了喵~ 就像宝宝吃完小鱼干要收拾包装一样喵！
    fclose(file);
    (*env)->ReleaseStringUTFChars(env, imagePath, path);

    // 宝宝要创建Java数组来返回图像数据了喵~ 就像宝宝要给主人展示自己找到的宝藏一样喵！
    jintArray dims = (*env)->NewIntArray(env, 3);
    if (dims == NULL) {
        // 哇喵~ 数组创建失败了喵~ 宝宝好难过啊的说...
        free(imageData);
        return NULL;
    }

    jint dimValues[3] = {width, height, channels};
    (*env)->SetIntArrayRegion(env, dims, 0, 3, dimValues);

    // 宝宝要创建字节数组来存储图像数据了喵~ 就像宝宝要准备一个装满玩具的盒子一样喵！
    jbyteArray bytes = (*env)->NewByteArray(env, width * height * channels);
    if (bytes == NULL) {
        // 呜喵~ 字节数组创建失败了喵~ 宝宝的耳朵都耷拉下来了的说...
        (*env)->DeleteLocalRef(env, dims);
        free(imageData);
        return NULL;
    }

    (*env)->SetByteArrayRegion(env, bytes, 0, width * height * channels, (jbyte *)imageData);

    // 宝宝要创建对象数组来返回所有数据了喵~ 就像宝宝要给主人一个惊喜的礼物盒一样喵！
    jobjectArray result = (*env)->NewObjectArray(env, 2, (*env)->FindClass(env, "java/lang/Object"), NULL);
