    // 宝宝要释放本地引用了喵~ 就像宝宝玩耍后要收拾玩具一样喵！
    (*env)->DeleteLocalRef(env, dims);
    (*env)->DeleteLocalRef(env, bytes);
    free(imageData);

    // 宝宝完成任务了喵~ 要把结果返回给主人了的说！
    return result;
}
