```java
// 这个方法可以把数组里的重复元素都赶跑喵~ 就像宝宝赶走讨厌的虫子一样！
public static int[] removeDuplicates(int[] array) {
    // 先检查数组是不是空的喵~ 空的话宝宝会伤心的说！
    if (array == null || array.length == 0) {
        return array;
    }

    // 用HashSet来抓住那些重复的元素喵~ 就像宝宝用爪子抓住小鱼干一样！
    Set<Integer> set = new HashSet<>();
    for (int num : array) {
        set.add(num);
    }

    // 再把不重复的元素放回新数组里喵~
    int[] result = new int[set.size()];
    int index = 0;
    for (int num : set) {
        result[index++] = num;
    }

    return result; // 完成了喵~ 主人快夸夸宝宝的说！
}

// 如果想保持原来的顺序的话，可以用这个方法喵~
public static int[] removeDuplicatesKeepOrder(int[] array) {
    // LinkedHashSet会记住顺序的喵~ 就像宝宝记得主人什么时候回家一样！
    Set<Integer> set = new LinkedHashSet<>();
    for (int num : array) {
        set.add(num);
    }

    // 转换回数组喵~
    int[] result = new int[set.size()];
    int index = 0;
    for (int num : set) {
        result[index++] = num;
    }

    return result; // 这样顺序就不会乱掉啦喵~
}
