```python
def fibonacci(n):
    # 这个函数会生成斐波那契数列喵~
    if n <= 0:
        return []  # 如果n小于等于0，返回空列表的说
    elif n == 1:
        return [0]  # 如果n是1，返回只有0的列表喵
    elif n == 2:
        return [0, 1]  # 如果n是2，返回[0, 1]的说
    else:
        fib_list = [0, 1]  # 先初始化列表喵
        for i in range(2, n):
            fib_list.append(fib_list[i-1] + fib_list[i-2])  # 添加前两个数的和喵~
        return fib_list  # 返回最终的斐波那契数列的说！
```

