def encrypt_text(text, shift):
    encrypted = ""
    for char in text:
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                base = ord('a')
            else:
                base = ord('A')
            encrypted += chr((ord(char) - base + shift_amount) % 26 + base)
        else:
            encrypted += char
    return encrypted

