    private class ButtonClickListener implements ActionListener {
        public void actionPerformed(ActionEvent event) {
            String command = event.getActionCommand(); // 获取按钮命令
            if (command.matches("[0-9.]")) { // 如果是数字或小数点
                if (start) { // 如果是开始新输入
