    // 计算方法，宝宝的小脑袋瓜会努力计算的喵~
    private void calculate(double x) {
        if (lastCommand.equals("+")) result += x; // 加法，宝宝会数数的说！
        else if (lastCommand.equals("-")) result -= x; // 减法，宝宝也会！
        else if (lastCommand.equals("*")) result *= x; // 乘法，稍微难一点但宝宝可以！
        else if (lastCommand.equals("/")) result /= x; // 除法，宝宝最拿手的喵~
        else if (lastCommand.equals("=")) result = x; // 等于，直接赋值

        display.setText("" + result); // 显示结果，宝宝会骄傲地展示！
    }

    // 主方法，程序的入口，就像宝宝的家门口一样重要喵~
