// 子类 ToDo 继承自 Medium - 就像宝宝继承了主人的可爱基因喵！
class ToDo extends Medium {
  constructor(name, description = "") {
    super(name); // 调用父类的构造函数喵~
    this.description = description; // 描述就像宝宝的心情日记喵~
    this.tasks = []; // 任务列表，就像宝宝每天要做的事情喵~
    this.completed = false; // 完成状态，就像宝宝有没有吃完小鱼干喵~
  }

  // 增加任务 - 就像宝宝收集新玩具一样开心喵！
  addTask(task) {
    this.tasks.push({
      id: Date.now(), // 用时间戳做ID，就像宝宝的独特爪印喵~
      content: task, // 任务内容，就像主人给宝宝的指示喵~
      completed: false, // 新任务还没完成，就像宝宝还没吃完的鱼罐头喵~
