  }

  // 删除任务 - 就像宝宝扔掉不喜欢的玩具喵~
  deleteTask(taskId) {
    const index = this.tasks.findIndex(task => task.id === taskId); // 找到要删除的任务喵~
    if (index !== -1) {
      const deletedTask = this.tasks[index];
      this.tasks.splice(index, 1); // 删除任务，就像宝宝把玩具丢进垃圾桶喵~
      return `任务 "${deletedTask.content}" 已删除`; // 告诉主人任务删除成功喵~
    }
    return "未找到指定任务"; // 如果找不到任务，宝宝会很困惑喵~
  }

  // 查询所有任务 - 就像宝宝展示自己的收藏品喵~
  getTasks() {
    if (this.tasks.length === 0) {
      return "当前没有任务"; // 没有任务，就像宝宝没有玩具一样可怜喵~
    }
    return this.tasks.map(task => 
      `ID: ${task.id}, 内容: ${task.content}, 状态: ${task.completed ? "已完成" : "未完成"}, 创建时间: ${task.createdTime}`
    ).join('\n'); // 把所有任务列出来，就像宝宝把玩具排成一排喵~
  }

  // 根据ID查询单个任务 - 就像宝宝在玩具堆里找特定的玩具喵~
  getTaskById(taskId) {
    const task = this.tasks.find(task => task.id === taskId); // 找到特定任务喵~
    if (task) {
      return `ID: ${task.id}, 内容: ${task.content}, 状态: ${task.completed ? "已完成" : "未完成"}, 创建时间: ${task.createdTime}`; // 显示任务详情喵~
    }
    return "未找到指定任务"; // 找不到任务，宝宝会很失落喵~
  }

  // 修改任务 - 就像宝宝给玩具换新衣服喵~
  updateTask(taskId, newContent) {
    const task = this.tasks.find(task => task.id === taskId); // 找到要修改的任务喵~
    if (task) {
      task.content = newContent; // 更新任务内容喵~
      task.updatedTime = new Date(); // 记录更新时间喵~
      return `任务已更新为: "${newContent}"`; // 告诉主人任务更新成功喵~
    }
    return "未找到指定任务"; // 找不到任务，宝宝会很困惑喵~
  }

  // 修改任务完成状态 - 就像宝宝标记自己吃完了小鱼干喵~
  toggleTaskStatus(taskId) {
    const task = this.tasks.find(task => task.id === taskId); // 找到要修改状态的任务喵~
    if (task) {
      task.completed = !task.completed; // 切换完成状态喵~
      task.updatedTime = new Date(); // 记录更新时间喵~
      return `任务 "${task.content}" 状态已更新为: ${task.completed ? "已完成" : "未完成"}`; // 告诉主人状态更新成功喵~
    }
    return "未找到指定任务"; // 找不到任务，宝宝会很失落喵~
  }

  // 重写父类方法 - 就像宝宝有自己的特色喵~
  getInfo() {
    return `待办事项: ${this.name}, 描述: ${this.description}, 创建时间: ${this.createdTime}, 任务数: ${this.tasks.length}`; // 显示更详细的信息喵~
  }
}
